async function h(): Promise<void> { await null; console.log("h"); }
async function main(): Promise<void> {
  console.log("start");
  const pending = (async () => {
    await null;
    console.log("iife after null");
  })();
  console.log("sync");
  await pending;
  await h();
  const x = await 5;
  const s = await "str";
  console.log(x, s);
  const f = async () => { const y = await 7; console.log(y); };
  await f();
  const v = await (async () => { await Promise.resolve(1); return 5; })();
  console.log(v);
}
